using System.Threading.Channels;using Microsoft.Extensions.Hosting;using Microsoft.Extensions.DependencyInjection;using Microsoft.Extensions.Logging;
var builder=Host.CreateApplicationBuilder();builder.Logging.ClearProviders();builder.Services.AddSingleton<QueueState>();builder.Services.AddScoped<Job>();builder.Services.AddHostedService<Worker>();using var host=builder.Build();await host.StartAsync();var state=host.Services.GetRequiredService<QueueState>();
foreach(int id in new[]{1,2,3})await state.Queue.Writer.WriteAsync(id);state.Queue.Writer.Complete();await state.Done.Task.WaitAsync(TimeSpan.FromSeconds(5));await host.StopAsync();Console.WriteLine($"processed:{state.Processed};failed:{state.Failed};disposed:{state.Disposed}");
class QueueState{public Channel<int> Queue=Channel.CreateBounded<int>(2);public TaskCompletionSource Done=new(TaskCreationOptions.RunContinuationsAsynchronously);public int Processed,Failed,Disposed;}
class Job(QueueState state):IDisposable{public async Task Run(int id,CancellationToken t){t.ThrowIfCancellationRequested();await Task.Yield();if(id==2)throw new InvalidOperationException("job");}public void Dispose()=>Interlocked.Increment(ref state.Disposed);}
class Worker(QueueState state,IServiceScopeFactory scopes):BackgroundService
{protected override async Task ExecuteAsync(CancellationToken t){try{await Task.WhenAll(Enumerable.Range(0,2).Select(_=>Consume(t)));state.Done.TrySetResult();}catch(Exception ex){state.Done.TrySetException(ex);throw;}}
private async Task Consume(CancellationToken t){await foreach(int id in state.Queue.Reader.ReadAllAsync(t)){using var scope=scopes.CreateScope();try{await scope.ServiceProvider.GetRequiredService<Job>().Run(id,t);}catch(InvalidOperationException){Interlocked.Increment(ref state.Failed);}finally{Interlocked.Increment(ref state.Processed);}}}}

